CREATE TABLE plantillas_mensaje(id BIGSERIAL PRIMARY KEY,codigo VARCHAR(50) NOT NULL UNIQUE,nombre VARCHAR(100) NOT NULL,categoria VARCHAR(40) NOT NULL,contenido TEXT NOT NULL,activo BOOLEAN NOT NULL DEFAULT TRUE,creado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,actualizado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0);
INSERT INTO plantillas_mensaje(codigo,nombre,categoria,contenido)VALUES('CITA_CONFIRMACION','Confirmación de cita','CITA','Hola {{paciente}}, tiene una cita el {{fecha}} a las {{hora}}. Responda CONFIRMO o solicite reprogramación.'),('CITA_RECORDATORIO','Recordatorio de cita','CITA','Le recordamos su cita de mañana a las {{hora}} en Consultorio Dental Americana.'),('POSTCONSULTA','Seguimiento postconsulta','SEGUIMIENTO','Hola {{paciente}}, ¿cómo se siente después de su atención? Puede responder con sus propias palabras.');
CREATE TABLE conversaciones_whatsapp(id BIGSERIAL PRIMARY KEY,paciente_id BIGINT REFERENCES pacientes(id) ON DELETE RESTRICT,telefono VARCHAR(20) NOT NULL,estado VARCHAR(20) NOT NULL DEFAULT 'ABIERTA',ultimo_mensaje_en TIMESTAMPTZ,creado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,actualizado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT chk_conversacion_estado CHECK(estado IN('ABIERTA','DERIVADA','CERRADA')));CREATE UNIQUE INDEX uq_conversacion_telefono_abierta ON conversaciones_whatsapp(telefono) WHERE estado<>'CERRADA';
CREATE TABLE mensajes_whatsapp(id BIGSERIAL PRIMARY KEY,conversacion_id BIGINT NOT NULL REFERENCES conversaciones_whatsapp(id) ON DELETE RESTRICT,paciente_id BIGINT REFERENCES pacientes(id) ON DELETE RESTRICT,cita_id BIGINT REFERENCES citas(id) ON DELETE RESTRICT,atencion_id BIGINT REFERENCES atenciones_clinicas(id) ON DELETE RESTRICT,direccion VARCHAR(10) NOT NULL,contenido TEXT NOT NULL,estado VARCHAR(20) NOT NULL,programado_para TIMESTAMPTZ,proveedor_id VARCHAR(150),intencion VARCHAR(40),requiere_revision BOOLEAN NOT NULL DEFAULT FALSE,error_detalle VARCHAR(500),creado_por BIGINT REFERENCES usuarios(id),creado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,enviado_en TIMESTAMPTZ,CONSTRAINT chk_mensaje_direccion CHECK(direccion IN('ENTRANTE','SALIENTE')),CONSTRAINT chk_mensaje_estado CHECK(estado IN('PENDIENTE','ENVIADO','ENTREGADO','LEIDO','RECIBIDO','FALLIDO','CANCELADO')));CREATE INDEX idx_mensaje_programado ON mensajes_whatsapp(estado,programado_para);CREATE INDEX idx_mensaje_conversacion ON mensajes_whatsapp(conversacion_id,creado_en DESC);
CREATE TABLE seguimientos_postconsulta(id BIGSERIAL PRIMARY KEY,paciente_id BIGINT NOT NULL REFERENCES pacientes(id) ON DELETE RESTRICT,atencion_id BIGINT NOT NULL REFERENCES atenciones_clinicas(id) ON DELETE RESTRICT,mensaje_id BIGINT REFERENCES mensajes_whatsapp(id) ON DELETE RESTRICT,programado_para TIMESTAMPTZ NOT NULL,estado VARCHAR(20) NOT NULL DEFAULT 'PROGRAMADO',respuesta TEXT,clasificacion VARCHAR(40),motivo_alerta VARCHAR(500),revisado_por BIGINT REFERENCES usuarios(id),revisado_en TIMESTAMPTZ,creado_por BIGINT NOT NULL REFERENCES usuarios(id),creado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,actualizado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT chk_seguimiento_estado CHECK(estado IN('PROGRAMADO','ENVIADO','RESPONDIDO','ALERTA','REVISADO','CERRADO')));CREATE INDEX idx_seguimiento_estado ON seguimientos_postconsulta(estado,programado_para);
